/**
 * What: Orchestrates test generation: loads the service model (CAP project, EDMX or snapshot),
 *     derives access rules and service paths, plans the tests, emits node:test files or a Postman
 *     collection, removes stale generated files and writes the result.
 * Why: One deterministic entry point used by the CLI and by CI; regeneration is idempotent and
 *     never touches hand-written tests.
 * If missing or unlinked: The odata-testgen CLI has nothing to run.
 */
import { mkdir, readdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { loadCapProjectInfo, loadCsn, loadServiceModel } from '@sapdx/sap-metadata';
import { accessFromCap, accessFromRolesFile } from './access.js';
import { emitNodeTests } from './emit-node.js';
import { emitPostman } from './emit-postman.js';
import { planTests } from './plan.js';

export const GENERATED_MARKER = 'GENERATED by odata-testgen';

export class GenerateError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = 'GenerateError';
  }
}

/**
 * @typedef {object} GenerateOptions
 * @property {string} input        CAP project folder, EDMX file or snapshot JSON
 * @property {'node-test' | 'postman'} emit
 * @property {string} [out]        node-test: folder (default <project>/test/generated); postman: file
 * @property {string} [roles]      roles.yaml (required for authorization tests on EDMX inputs)
 * @property {string} [service]    only this service
 * @property {string} [basePath]   URL path of the service (EDMX inputs), e.g. /sap/opu/odata4/...
 * @property {string[]} [exclude]  entity sets to skip
 */

/**
 * @param {GenerateOptions} options
 */
export async function generateTests(options) {
  const { input, emit } = options;
  if (!['node-test', 'postman'].includes(emit)) throw new GenerateError(`Unknown --emit "${emit}" (node-test or postman)`);
  const isCap = (await stat(input).catch(() => undefined))?.isDirectory() ?? false;
  if (emit === 'node-test' && !isCap) throw new GenerateError('node-test output needs a CAP project as input (it runs in-process with cds.test); use --emit postman for EDMX inputs');

  let model = await loadServiceModel(input);
  if (options.service) {
    model = { ...model, services: model.services.filter((s) => s.name === options.service) };
    if (!model.services.length) throw new GenerateError(`Service ${options.service} not found in ${input}`);
  }

  let access;
  /** @type {Record<string, string>} */
  let paths = {};
  if (isCap) {
    const info = await loadCapProjectInfo(input);
    paths = info.paths;
    access = accessFromCap(await loadCsn(input), info.users);
  }
  if (options.roles) access = await accessFromRolesFile(options.roles);
  if (options.basePath) for (const s of model.services) paths[s.name] = options.basePath.replace(/\/$/, '');

  const exclude = new Set(options.exclude ?? []);
  const plans = planTests(model, { access, paths, include: (set) => !exclude.has(set.name) && !set.name.endsWith('_texts') });
  const command = `npx odata-testgen --input ${isCap ? '.' : path.basename(input)} --emit ${emit}${options.service ? ` --service ${options.service}` : ''}`;

  if (emit === 'node-test') {
    const outDir = path.resolve(options.out ?? path.join(input, 'test', 'generated'));
    const projectRoot = path.relative(outDir, path.resolve(input)).replaceAll('\\', '/') || '.';
    const files = emitNodeTests(plans, { projectRoot, command });
    const removed = await removeStale(outDir, new Set(files.map((f) => f.path)));
    await mkdir(outDir, { recursive: true });
    for (const f of files) await writeFile(path.join(outDir, f.path), f.content);
    return { plans, files: files.map((f) => path.join(outDir, f.path)), removed, users: access?.users ?? [] };
  }

  const target = path.resolve(options.out ?? 'odata-tests.postman_collection.json');
  const collection = emitPostman(plans, { name: model.services.map((s) => s.name).join(', '), command });
  await mkdir(path.dirname(target), { recursive: true });
  await writeFile(target, `${JSON.stringify(collection, null, 2)}\n`);
  return { plans, files: [target], removed: [], users: access?.users ?? [] };
}

/**
 * Deletes previously generated files that are no longer produced (e.g. entity set removed).
 * Only files carrying the generated marker are touched.
 * @param {string} dir
 * @param {Set<string>} keep
 */
async function removeStale(dir, keep) {
  /** @type {string[]} */
  const removed = [];
  /** @type {string[]} */
  let entries;
  try {
    entries = await readdir(dir);
  } catch {
    return removed;
  }
  for (const name of entries.sort()) {
    if (keep.has(name) || !name.endsWith('.test.js')) continue;
    const file = path.join(dir, name);
    if ((await readFile(file, 'utf8')).includes(GENERATED_MARKER)) {
      await rm(file);
      removed.push(file);
    }
  }
  return removed;
}
